/bin/bash -lc "python3 - <<'PY'
import uno

URL = 'uno:socket,host=localhost,port=2002;urp;StarOffice.ComponentContext'
local_ctx = uno.getComponentContext()
resolver = local_ctx.ServiceManager.createInstanceWithContext('com.sun.star.bridge.UnoUrlResolver', local_ctx)
ctx = resolver.resolve(URL)
smgr = ctx.ServiceManager
desktop = smgr.createInstanceWithContext('com.sun.star.frame.Desktop', ctx)
doc = desktop.getCurrentComponent()

if not doc or not doc.supportsService('com.sun.star.text.TextDocument'):
    raise SystemExit('No Writer document is active')

APOSTROPHES = {\"'\", \"\\u2019\", \"\\u2018\"}

def cap_first_letters(s: str) -> str:
    out = []
    prev = ''
    for ch in s:
        if ch.isalpha() and not (prev.isalpha() or prev in APOSTROPHES):
            out.append(ch.upper())
        else:
            out.append(ch)
        prev = ch
    return ''.join(out)

def process_text(text):
    changed = 0
    enum = text.createEnumeration()
    while enum.hasMoreElements():
        para = enum.nextElement()
        if not hasattr(para, 'createEnumeration'):
            continue
        portions = para.createEnumeration()
        while portions.hasMoreElements():
            portion = portions.nextElement()
            try:
                portion_type = portion.TextPortionType
            except Exception:
                portion_type = 'Text'
            if portion_type "'!= '"'Text':
                continue
            old = portion.String
            new = cap_first_letters(old)
            if new "'!= old:
                portion.String = new
                changed += 1
    return changed

changed = process_text(doc.Text)

# Include headers and footers from any page styles that use them.
try:
    styles = doc.StyleFamilies.getByName('"'PageStyles')
    for name in styles.ElementNames:
        style = styles.getByName(name)
        for attr in ('HeaderText', 'FooterText'):
            try:
                if getattr(style, attr):
                    changed += process_text(getattr(style, attr))
            except Exception:
                pass
except Exception:
    pass

# Include text frames if present.
try:
    frames = doc.TextFrames
    for name in frames.ElementNames:
        changed += process_text(frames.getByName(name).Text)
except Exception:
    pass

doc.store()
print(f'changed_portions={changed}')
print(f'url={doc.URL}')
PY"

